pragma solidity >=0.8.0;

contract RevertProbe {
    uint256 public count;

    error BadInput(uint256 v);

    function okAdd(uint256 x) external {
        count += x;
    }

    function reqMsg(bool cond) external pure returns (uint256) {
        require(cond, "req-fail-msg");
        return 1;
    }

    function assertFail(uint256 x) external pure returns (uint256) {
        assert(x != 0);
        return x;
    }

    function divZero(uint256 x) external pure returns (uint256) {
        return 10 / x;
    }

    function overflow() external pure returns (uint256) {
        uint256 m = type(uint256).max;
        return m + 1;
    }

    function oob(uint256 i) external pure returns (uint256) {
        uint256[2] memory a = [uint256(1), uint256(2)];
        return a[i];
    }

    function customErr(uint256 x) external pure returns (uint256) {
        if (x == 0) revert BadInput(x);
        return x;
    }
}

pragma solidity >=0.8.0;

contract EventProbe {
    event Simple(uint256 x);
    event TwoIndexed(address indexed who, uint256 indexed val, string note);
    event ThreeIndexed(address indexed a, bytes32 indexed b, uint256 indexed c, string payload);
    event IndexedString(string indexed tag, uint256 v);

    uint256 public count;

    constructor() {
        emit Simple(1);
        emit TwoIndexed(msg.sender, 42, "ctor");
    }

    function emitMany(string calldata tag, uint256 v) external {
        count += 1;
        emit Simple(v);
        emit TwoIndexed(msg.sender, v, tag);
        emit IndexedString(tag, v);
        emit ThreeIndexed(msg.sender, keccak256(bytes(tag)), v, tag);
        emit Simple(v + 1);
    }

    function emitDupes(uint256 n) external {
        for (uint256 i = 0; i < n; i++) {
            emit Simple(i);
            emit Simple(i);
        }
        count += n;
    }

    function getCount() external view returns (uint256) {
        return count;
    }
}

pragma solidity >=0.8.0;
contract CryptoPackedProbe {
    bytes32 public hPacked;
    bytes32 public hEncoded;
    bytes32 public hSha;
    bool public packedEqualsEncoded;

    event Hashes(bytes32 packedH, bytes32 encodedH, bytes32 shaH);

    function compute(uint8 x, string memory s, bytes memory b) external {
        hPacked = keccak256(abi.encodePacked(x, s, b));
        hEncoded = keccak256(abi.encode(x, s, b));
        hSha = sha256(abi.encodePacked(x, s, b));
        packedEqualsEncoded = hPacked == hEncoded;
        emit Hashes(hPacked, hEncoded, hSha);
    }

    function getPacked() external view returns (bytes32) { return hPacked; }
    function getEncoded() external view returns (bytes32) { return hEncoded; }
    function getSha() external view returns (bytes32) { return hSha; }
    function getPackedEqualsEncoded() external view returns (bool) { return packedEqualsEncoded; }
}

pragma solidity >=0.8.0;
contract IntCasts {
    int256 public last;
    function arithShift(int64 x) external returns (int256) {
        int64 r = x >> 3;
        last = r;
        return r;
    }
    function divTrunc(int64 a, int64 b) external returns (int256) {
        int64 r = a / b;
        last = r;
        return r;
    }
    function modTrunc(int64 a, int64 b) external returns (int256) {
        int64 r = a % b;
        last = r;
        return r;
    }
    function castChain(int16 x) external returns (int256) {
        uint8 u = uint8(uint16(x));
        int64 r = int64(uint64(u));
        last = r;
        return r;
    }
    function bytesShift(bytes4 b) external returns (int256) {
        uint32 u = uint32(b);
        int64 r = int64(uint64(u >> 1));
        last = r;
        return r;
    }
    function readLast() external view returns (int256) {
        return last;
    }
}

pragma solidity >=0.8.0;

contract EnvProbe {
    bytes32 public lastHash;
    uint256 public lastNumber;
    uint256 public calls;

    function capture() external returns (bytes32 h, uint256 n) {
        h = blockhash(block.number - 1);
        n = block.number;
        lastHash = h;
        lastNumber = n;
        calls += 1;
    }

    function readNumber() external view returns (uint256) {
        return block.number;
    }

    function getLastHash() external view returns (bytes32) {
        return lastHash;
    }
}

pragma solidity >=0.8.0;

contract StringBytesAbi {
    string public stored;
    bytes public blob;
    string[] public names;
    uint256 public count;

    event Echo(string s, bytes b);
    event Named(uint256 indexed idx, string name);

    function store(string calldata s) external {
        stored = s;
        count += 1;
        emit Echo(s, bytes(s));
    }

    function storeBytes(bytes calldata b) external {
        blob = b;
        count += 1;
        emit Echo("", b);
    }

    function join(string calldata a, string calldata b) external pure returns (string memory) {
        return string.concat(a, b);
    }

    function catBytes(bytes calldata a, bytes calldata b) external pure returns (bytes memory) {
        return bytes.concat(a, b);
    }

    function len(string calldata s) external pure returns (uint256) {
        return bytes(s).length;
    }

    function pushName(string calldata n) external {
        names.push(n);
        count += 1;
        emit Named(names.length - 1, n);
    }

    function nameAt(uint256 i) external view returns (string memory) {
        return names[i];
    }
}
